#include "sim_audit.hpp"
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
#include <chrono>
using json=nlohmann::ordered_json;using namespace hbf_eventlab;
void need(bool v,const char*s){if(!v)throw std::runtime_error(s);}
int main(int argc,char**argv)try{need(argc==3,"config result");std::ifstream f(argv[1]);json c;f>>c;std::ifstream ini(c.at("ini").get<std::string>());auto resolved=resolve_configuration(read_configuration(ini,"common clock A"));std::vector<TensorRegion> regions;for(auto&r:c.at("regions"))regions.push_back({r.at("tensor"),GlobalByteAddress{r.at("global_base").get<uint64_t>()},r.at("valid_bytes"),1});OnlineAudit audit;TensorAccessBridge bridge(resolved,regions,{},&audit);auto wall=std::chrono::steady_clock::now();for(auto&r:regions){audit.begin(Op::Write,r.base.value,r.bytes);auto x=bridge.initialize(r.name);need(x.complete&&x.success,"init");audit.end(x.registered_globals,x.finished_globals,x.completed->value);}auto t0=bridge.session().now().value;uint64_t compute=0,wait=0,parents=0,bytes=0;json tokens=json::array();auto chunk=c.value("chunk",4096u);bridge.set_chunk_for_comparison(chunk);audit.global_bytes=chunk;
for(auto&a:c.at("actions")){auto kind=a.at("kind").get<std::string>();if(kind=="compute"){auto n=a.at("ps").get<uint64_t>();need(bridge.advance_compute(Tick{n}).success,"compute");compute+=n;}else if(kind=="read"){auto name=a.at("tensor").get<std::string>();auto it=std::find_if(regions.begin(),regions.end(),[&](const auto&r){return r.name==name;});need(it!=regions.end(),"tensor");auto offset=a.at("offset").get<uint64_t>(),n=a.at("bytes").get<uint64_t>();audit.begin(Op::Read,it->base.value+offset,n);auto x=bridge.access(name,offset,n);if(!x.complete||!x.success)throw std::runtime_error("read: "+x.reason);audit.end(x.registered_globals,x.finished_globals,x.completed->value);wait+=x.completed->value-x.offered.value;bytes+=n;parents+=chunk==512?n/512:1;}else if(kind=="token"){auto relative=bridge.session().now().value-t0;need(relative==compute+wait,"conservation");tokens.push_back({{"step",a.at("step")},{"ps",relative},{"compute_ps",compute},{"wait_ps",wait}});}else throw std::runtime_error("action");}
auto finish=bridge.finish();need(finish.run.workload_success&&finish.run.host.drained()&&finish.run.device.drained(),"drain");need(!audit.failures&&!audit.attempt_errors,"audit");std::ofstream(argv[2])<<json({{"status","pass"},{"tokens",tokens},{"compute_ps",compute},{"wait_ps",wait},{"bytes",bytes},{"client_parents",parents},{"read_fragments",audit.total_read_fragments},{"events",finish.run.events},{"run_wall_s",std::chrono::duration<double>(std::chrono::steady_clock::now()-wall).count()}}).dump(2);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
